import{_ as e,o as l,c as i,a2 as a}from"./chunks/framework.D66Xq0Kv.js";const y=JSON.parse('{"title":"Qwen3-VL 端侧性能","description":"","frontmatter":{},"headers":[],"relativePath":"LLM推理/Qwen3-VL端侧性能.md","filePath":"LLM推理/Qwen3-VL端侧性能.md","lastUpdated":null}'),s={name:"LLM推理/Qwen3-VL端侧性能.md"};function d(n,t,r,h,g,o){return l(),i("div",null,[...t[0]||(t[0]=[a(`<h1 id="qwen3-vl-端侧性能" tabindex="-1">Qwen3-VL 端侧性能 <a class="header-anchor" href="#qwen3-vl-端侧性能" aria-label="Permalink to &quot;Qwen3-VL 端侧性能&quot;">​</a></h1><blockquote><p>Qwen3-VL-2B 在 RK3588 上的一次实测：纯文本三轮、图文三轮，记录首 token 时间、解码速度和峰值内存。测试时间 2026-10-10 15:21（UTC+8）。</p></blockquote><h2 id="测试路径" tabindex="-1">测试路径 <a class="header-anchor" href="#测试路径" aria-label="Permalink to &quot;测试路径&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph 纯文本[&quot;纯文本&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        T1[&quot;提示分词&quot;] --&gt; T2[&quot;语言模型 prefill + decode&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph 图文[&quot;图文&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        V1[&quot;图像缩放 448×448&quot;] --&gt; V2[&quot;视觉模型编码&lt;br/&gt;196 个图像 token&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        V2 --&gt; V3[&quot;图像 token + 文本 token&quot;] --&gt; V4[&quot;语言模型 prefill + decode&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span></code></pre></div><p>图文用的是一张 1024×640 的照片，运行时先补成方形，再缩放到 448×448；纯文本不加载视觉模型。</p><h2 id="条件" tabindex="-1">条件 <a class="header-anchor" href="#条件" aria-label="Permalink to &quot;条件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>平台</td><td>RK3588，CPU 绑在大核 4、5、6、7</td></tr><tr><td>语言模型</td><td>Qwen3-VL-2B 指令模型，W8A8，RKLLM</td></tr><tr><td>视觉模型</td><td>输入 448×448，FP16，RKNN</td></tr><tr><td>转换工具</td><td>RKLLM-Toolkit 1.2.3</td></tr><tr><td>板端运行时</td><td>RKLLM Runtime 1.3.1</td></tr><tr><td>NPU 驱动</td><td>0.9.8</td></tr><tr><td>NPU 核数</td><td>3</td></tr><tr><td>上下文上限</td><td>4096</td></tr><tr><td>单次生成上限</td><td>128</td></tr><tr><td>日志</td><td>打开运行时性能日志</td></tr></tbody></table><p>首 token 取运行时表格里 Prefill 的总时间；解码速度取生成阶段的每秒 token。模型经常在 128 个 token 之前遇到结束符，所以各轮生成长度不同。句与句之间清空了 KV，测到的是冷前缀，没有命中上一句留下的键值。</p><h2 id="总结果" tabindex="-1">总结果 <a class="header-anchor" href="#总结果" aria-label="Permalink to &quot;总结果&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th style="text-align:right;">首 token（三轮均值）</th><th style="text-align:right;">解码速度（三轮均值）</th><th style="text-align:right;">峰值内存</th></tr></thead><tbody><tr><td>纯文本</td><td style="text-align:right;">141 ms</td><td style="text-align:right;">10.55 tok/s</td><td style="text-align:right;">2279 MB</td></tr><tr><td>图文</td><td style="text-align:right;">1097 ms</td><td style="text-align:right;">10.30 tok/s</td><td style="text-align:right;">3157 MB</td></tr></tbody></table><blockquote><p>核心结论：</p><ul><li><strong>图像不改变解码速度</strong>——解码阶段两边都是每 token 约 94–98 ms，回复变长只是这个速度乘上 token 数。</li><li><strong>图文慢在 prefill</strong>：视觉模型编出 196 个图像 token，加问题文本后 prefill 约 210 个 token，时间稳定在 1.08–1.12 s，约是纯文本首 token 的 8 倍。</li><li><strong>图像编码本身 2196 ms</strong>。本次演示在进对话前做一次，没算进每轮 prefill；若每次请求都重新编码，用户看到第一个字约 2196 + 1097 = 3293 ms。</li></ul></blockquote><h2 id="纯文本" tabindex="-1">纯文本 <a class="header-anchor" href="#纯文本" aria-label="Permalink to &quot;纯文本&quot;">​</a></h2><p>语言模型加载 8102 ms，运行时在第一轮另报初始化 6620 ms——发生在进对话之前，不计入首 token。峰值内存约 2279 MB。</p><p>三轮 prefill 均值 140.7 ms，解码均值 10.55 tok/s。短句的 prefill token 很少，用每秒 token 会把固定开销摊薄，比较时看总时间。</p><table tabindex="0"><thead><tr><th>问题</th><th style="text-align:right;">首 token</th><th style="text-align:right;">Prefill tokens</th><th style="text-align:right;">Prefill tok/s</th><th style="text-align:right;">解码耗时</th><th style="text-align:right;">生成 tokens</th><th style="text-align:right;">解码 tok/s</th><th style="text-align:right;">内存</th></tr></thead><tbody><tr><td>你好</td><td style="text-align:right;">174.0 ms</td><td style="text-align:right;">9</td><td style="text-align:right;">51.7</td><td style="text-align:right;">767 ms</td><td style="text-align:right;">8</td><td style="text-align:right;">10.43</td><td style="text-align:right;">2278 MB</td></tr><tr><td>用一句话介绍 RK3588</td><td style="text-align:right;">117.8 ms</td><td style="text-align:right;">16</td><td style="text-align:right;">135.8</td><td style="text-align:right;">3308 ms</td><td style="text-align:right;">35</td><td style="text-align:right;">10.58</td><td style="text-align:right;">2279 MB</td></tr><tr><td>请用两句话说明什么是 KV cache</td><td style="text-align:right;">130.2 ms</td><td style="text-align:right;">16</td><td style="text-align:right;">122.9</td><td style="text-align:right;">6014 ms</td><td style="text-align:right;">64</td><td style="text-align:right;">10.64</td><td style="text-align:right;">2279 MB</td></tr></tbody></table><h2 id="图文" tabindex="-1">图文 <a class="header-anchor" href="#图文" aria-label="Permalink to &quot;图文&quot;">​</a></h2><p>同一张照片。视觉模型加载 4808 ms、图像编码 2196 ms，这两项在进程里只做一次，发生在对话循环之前；语言模型加载 4775 ms、第一轮初始化 3717 ms，同样不计入首 token。</p><p>三轮 prefill 均值 1097.2 ms，解码均值 10.30 tok/s。峰值内存约 3157 MB，比纯文本高约 878 MB。</p><table tabindex="0"><thead><tr><th>问题</th><th style="text-align:right;">首 token</th><th style="text-align:right;">Prefill tokens</th><th style="text-align:right;">Prefill tok/s</th><th style="text-align:right;">解码耗时</th><th style="text-align:right;">生成 tokens</th><th style="text-align:right;">解码 tok/s</th><th style="text-align:right;">内存</th></tr></thead><tbody><tr><td>用一句话描述这张图片</td><td style="text-align:right;">1083 ms</td><td style="text-align:right;">211</td><td style="text-align:right;">194.8</td><td style="text-align:right;">2931 ms</td><td style="text-align:right;">30</td><td style="text-align:right;">10.24</td><td style="text-align:right;">3157 MB</td></tr><tr><td>图里有什么？</td><td style="text-align:right;">1116 ms</td><td style="text-align:right;">210</td><td style="text-align:right;">188.1</td><td style="text-align:right;">12321 ms</td><td style="text-align:right;">127</td><td style="text-align:right;">10.31</td><td style="text-align:right;">3157 MB</td></tr><tr><td>这张图的主体是什么？</td><td style="text-align:right;">1092 ms</td><td style="text-align:right;">212</td><td style="text-align:right;">194.1</td><td style="text-align:right;">7045 ms</td><td style="text-align:right;">73</td><td style="text-align:right;">10.36</td><td style="text-align:right;">3157 MB</td></tr></tbody></table><p>127 个 token 那一轮碰到了生成上限，解码耗时约 12.3 s，速度仍是每秒 10.31 个 token。</p><h2 id="怎么用这些数" tabindex="-1">怎么用这些数 <a class="header-anchor" href="#怎么用这些数" aria-label="Permalink to &quot;怎么用这些数&quot;">​</a></h2><ul><li><strong>首 token 是 prefill 的时间</strong>。模型加载和初始化在进对话前完成，用户已在会话里时，不再把那几秒加进去；进程刚拉起的第一句，要把加载时间另算。</li><li><strong>本表每轮都清空了 KV</strong>。若上一句的键值还留着，新问题的 prefill 只覆盖新增文本，时间会靠近上面的纯文本短句，而不是再付一遍 1.1 s。</li><li><strong>图像编码在进程里复用</strong>，所以表里图文首 token 不含 2196 ms。业务侧若每次请求都重新编码，首字按「编码 2196 ms + 冷 prefill 约 1097 ms」估计。在线若只保留一轮历史、每轮清空或几乎无法命中前缀，就不能改用「命中历史之后的短 prefill」。</li><li><strong>解码速度对生成长度不敏感</strong>：本次在 8 和 127 个 token 上都约 10.3 tok/s；另一次把生成上限放到 1024、实际生成 11/276/459 个 token 的交互，解码为 10.25/9.94/9.39 tok/s，同一量级。生成变长几乎不改变每秒 token，只拉长总时间。</li></ul>`,22)])])}const k=e(s,[["render",d]]);export{y as __pageData,k as default};
